-- Vastra production schema (PostgreSQL/Prisma-ready)
CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, description TEXT, status TEXT DEFAULT 'active');
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, category_id INT REFERENCES categories(id), description TEXT, price NUMERIC(10,2) NOT NULL, mrp NUMERIC(10,2) NOT NULL, discount INT DEFAULT 0, sku TEXT UNIQUE NOT NULL, stock INT DEFAULT 0, brand TEXT DEFAULT 'Vastra', fabric TEXT, color TEXT, pattern TEXT, occasion TEXT, status TEXT DEFAULT 'active', created_at TIMESTAMP DEFAULT now(), updated_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, phone TEXT, password_hash TEXT, role TEXT DEFAULT 'customer', created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id), order_number TEXT UNIQUE NOT NULL, status TEXT DEFAULT 'pending', subtotal NUMERIC(10,2), discount NUMERIC(10,2) DEFAULT 0, shipping NUMERIC(10,2) DEFAULT 0, total NUMERIC(10,2), payment_status TEXT DEFAULT 'pending', payment_method TEXT, shipping_address JSONB, created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id SERIAL PRIMARY KEY, order_id INT REFERENCES orders(id), product_id INT REFERENCES products(id), product_name_snapshot TEXT, sku_snapshot TEXT, price_snapshot NUMERIC(10,2), quantity INT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id), product_id INT REFERENCES products(id), rating INT CHECK (rating BETWEEN 1 AND 5), title TEXT, comment TEXT, status TEXT DEFAULT 'pending', created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS coupons (id SERIAL PRIMARY KEY, code TEXT UNIQUE NOT NULL, type TEXT NOT NULL, value NUMERIC(10,2) NOT NULL, min_order_value NUMERIC(10,2) DEFAULT 0, max_discount NUMERIC(10,2), status TEXT DEFAULT 'active');
